python3 - <<'EOF'
import json,hashlib,os,re
S='/tmp/opensip-design-corrections/candidate-subject.v37/'
MAN='/Users/sb/code/opensip-ai/opensip_arch/docs/coop/design-corrections/reviews/candidate-subject.v37.json'
def rows(o):
    if isinstance(o,list) and o and isinstance(o[0],dict) and 'path' in o[0] and 'sha256' in o[0]: return o
    if isinstance(o,dict):
        for v in o.values():
            x=rows(v)
            if x: return x
man={r['path']:r['sha256'] for r in rows(json.load(open(MAN)))}
def load_verified(rel):
    b=open(S+rel,'rb').read(); assert hashlib.sha256(b).hexdigest()==man[rel], rel; return b
ids=json.loads(load_verified('docs/coop/design-corrections/foundation/identity-schemas.v3.json'))
reg=ids.get('x-opensip-payload-registry')
print('PAYLOAD REGISTRY keys', list(reg.keys()) if isinstance(reg,dict) else type(reg))
docs=set()
for cname,body in (reg.get('classes') or {}).items():
    if 'document' in body: docs.add((cname,body['document']))
    for rn,row in (body.get('rows') or {}).items(): docs.add((cname+'/'+rn,row['document']))
for d in sorted(docs): print('  registered',d)
dd=ids.get('x-opensip-digest-domains')
print('DIGEST DOMAINS type',type(dd).__name__)
txt=json.dumps(dd)
for k in ('invocation','query','envelope','termination','step'):
    print('  domain mentions',k, [m.group(0) for m in re.finditer(r'"[^"]*'+k+r'[^"]*"',txt,re.I)][:12])
av=ids.get('$defs',{}).get('availability')
print('AVAILABILITY DEF', json.dumps(av)[:1500])
ov=json.load(open('/private/tmp/opensip-design-corrections/claude-source37-root-corrections-review.v1/subject-manifest.json'))
needles={f['beforeSha256']:f['path'] for f in ov['files']}
urns=['urn:opensip:product-v1:workflows:evaluator3:common:3','urn:opensip:product-v1:workflows:common','urn:opensip:product-v1:workflows:evaluator3:graph-query:3','graph-query.schema.json','evaluator3/common.schema.json','schemas/common.schema.json']
hits={}
for rel in man:
    if '/reviews/' in rel: continue
    if not rel.endswith(('.json','.md','.py','.sql','.txt','.yaml','.yml','.toml')): continue
    try: t=open(S+rel,encoding='utf-8').read()
    except Exception: continue
    for sh,p in needles.items():
        if sh in t: hits.setdefault('SHA:'+p,[]).append(rel)
    for u in urns:
        if u in t: hits.setdefault('REF:'+u,[]).append(rel)
for k,v in sorted(hits.items()):
    print(k, len(v)); [print('    ',x) for x in v[:40]]
EOF
